const CACHE = 'qb-files';
const MAP = new Map(FILES);
const SCOPE = new URL(self.registration.scope);
const key = (p, h) => new URL(p + '?h=' + h, SCOPE).href;
const BIG = /^(fig|img)\//;          // pictures: saved after the questions, in the background

async function put(c, p, h) {
  const k = key(p, h);
  if (await c.match(k)) return false;
  const r = await fetch(new URL(p, SCOPE).href, {cache: 'no-cache'});
  if (!r.ok) throw new Error(p + ' ' + r.status);
  await c.put(k, r);
  return true;
}
async function pool(list, fn, n, each) {
  let i = 0, done = 0;
  await Promise.all(Array.from({length: n}, async () => {
    while (i < list.length) { const x = list[i++]; await fn(x); done++; if (each) each(done); }
  }));
}
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE)
    .then(c => pool(FILES.filter(f => !BIG.test(f[0])), ([p, h]) => put(c, p, h), 8))
    .then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    const keep = new Set(FILES.map(([p, h]) => key(p, h)));
    const c = await caches.open(CACHE);
    for (const r of await c.keys()) if (!keep.has(r.url)) await c.delete(r);
    for (const n of await caches.keys()) if (n !== CACHE) await caches.delete(n);
    await self.clients.claim();
  })());
});
let filling = null;
function fill(client) {
  if (filling) return filling;
  filling = (async () => {
    const c = await caches.open(CACHE), todo = [];
    for (const [p, h] of FILES) if (!(await c.match(key(p, h)))) todo.push([p, h]);
    const total = todo.length; let fetched = 0, last = 0;
    if (total) await pool(todo, async ([p, h]) => { try { if (await put(c, p, h)) fetched++; } catch (x) {} }, 6, d => {
      const now = Date.now();
      if (client && (now - last > 400 || d === total)) { last = now; client.postMessage({type: 'fill-progress', done: d, total}); }
    });
    if (client) client.postMessage({type: 'fill-done', fetched, total});
  })().finally(() => { filling = null; });
  return filling;
}
self.addEventListener('message', e => { if (e.data && e.data.type === 'fill') e.waitUntil(fill(e.source)); });

function fromCache(p) {
  const h = MAP.get(p);
  return h ? caches.open(CACHE).then(c => c.match(key(p, h))) : Promise.resolve(undefined);
}
function networkFirst(req, p) {            // the page and version.js: newest when online, saved copy when not
  return new Promise(resolve => {
    let settled = false;
    const fallback = () => fromCache(p).then(r => { if (!settled) { settled = true; resolve(r || Response.error()); } });
    const t = setTimeout(fallback, 4000);
    fetch(req).then(r => { if (settled) return; clearTimeout(t); settled = true; resolve(r); },
                    () => { clearTimeout(t); fallback(); });
  });
}
self.addEventListener('fetch', e => {
  const u = new URL(e.request.url);
  if (e.request.method !== 'GET' || u.origin !== SCOPE.origin || !u.pathname.startsWith(SCOPE.pathname)) return;
  let p = u.pathname.slice(SCOPE.pathname.length) || 'index.html';
  if (e.request.mode === 'navigate') p = 'index.html';
  if (p === 'index.html' || p === 'version.js') { e.respondWith(networkFirst(e.request, p)); return; }
  const h = MAP.get(p);
  if (!h) return;
  e.respondWith(caches.open(CACHE).then(async c => {
    const hit = await c.match(key(p, h));
    if (hit) return hit;
    const r = await fetch(e.request);
    if (r.ok) c.put(key(p, h), r.clone());
    return r;
  }));
});
